using System;
using System.Collections.Generic;
using System.Threading.Tasks;

public record IdempotencyRecord(int StatusCode, string ResponseBody);

public class IdempotencyManager
{
    private readonly Dictionary<string, IdempotencyRecord> _cache = new();

    public async Task<(bool isCached, IdempotencyRecord? record)> CheckOrExecuteAsync(
        string idempotencyKey, 
        Func<Task<IdempotencyRecord>> operation)
    {
        if (_cache.TryGetValue(idempotencyKey, out var existing))
        {
            return (true, existing);
        }

        var newRecord = await operation();
        _cache[idempotencyKey] = newRecord;
        return (false, newRecord);
    }
}

public class Program
{
    public static async Task Main()
    {
        var manager = new IdempotencyManager();
        var key = "tx-order-payment-uuid-12345";

        int executionCount = 0;
        Func<Task<IdempotencyRecord>> processPayment = async () =>
        {
            executionCount++;
            Console.WriteLine($"[PAYMENT GATEWAY] Memproses transaksi debit rekening... (Eksekusi ke-{executionCount})");
            await Task.Delay(10);
            return new IdempotencyRecord(200, "{\"status\":\"SUCCESS\", \"txId\":\"TX-9982\"}");
        };

        Console.WriteLine("--- Request 1 Datang ---");
        var res1 = await manager.CheckOrExecuteAsync(key, processPayment);
        Console.WriteLine($"Cached: {res1.isCached}, Status: {res1.record?.StatusCode}, Body: {res1.record?.ResponseBody}");

        Console.WriteLine("\n--- Request 2 Datang (Retry dengan Key Sama) ---");
        var res2 = await manager.CheckOrExecuteAsync(key, processPayment);
        Console.WriteLine($"Cached: {res2.isCached}, Status: {res2.record?.StatusCode}, Body: {res2.record?.ResponseBody}");

        Console.WriteLine($"\nTotal Eksekusi Nyata: {executionCount} (Harus tepat 1!)");
    }
}

